INSERT INTO `landing_setting` (`id`, `active_variant`, `brand_color`, `hero_h1`, `hero_bn`, `hero_lead`, `hero_eyebrow`, `cta_primary_label`, `cta_secondary_label`, `pricing_mode`, `pricing_headline`, `pricing_future_note`, `show_features`, `show_pricing`, `show_testimonials`, `show_schools`, `updated_by`, `updated_at`) VALUES
(1, 'a', '#1f9d55', 'Run your school in 5 minutes — on us.', 'আপনার স্কুলের জন্য সম্পূর্ণ ফ্রি স্কুল ম্যানেজমেন্ট — কোনো কার্ড লাগবে না।', 'Admissions, attendance, exams, fees, accounting, parent SMS and your own public school website — all in Bengali and English, on your own schoolname.smartschool.bd. Every feature, for every school, free for now.', 'Free for every Bangladeshi school — no card, no limits', 'Sign your school up — free', 'See what is included', 'free', 'One plan. Everything included.', 'In a few months — once we have more schools onboard and server costs start adding up — we will introduce optional paid plans for the heavier features (custom domain, REST API, large storage). Anything you create today stays on the free plan; you will never be forced to pay to keep your existing data running.', 1, 1, 1, 1, NULL, '2026-06-06 15:03:39');
